source("config.R"); source("R/utils.R"); load_project_packages(); ensure_dirs()
x <- readRDS("data/processed/grid_analysis.rds"); mp <- readRDS("data/interim/microplastics_clean.rds"); bio <- readRDS("data/interim/biodiversity_clean.rds")
point_map <- function(points, title, file, colour) { p <- ggplot2::ggplot() + ggplot2::geom_sf(data = study_area(cfg), fill = "#eaf3f8", colour = "grey70") + ggplot2::geom_sf(data = points, colour = colour, alpha = .65, size = .8) + ggplot2::labs(title = title, x = "Longitude", y = "Latitude") + ggplot2::coord_sf(expand = FALSE) + ggplot2::theme_minimal(base_size = 12); ggplot2::ggsave(file, p, width = 12, height = 7, dpi = 300) }
point_map(mp, "Microplastic observation locations", "outputs/maps/microplastic_observation_locations.png", "#d7301f")
point_map(bio, "Biodiversity observation locations", "outputs/maps/biodiversity_observation_locations.png", "#225ea8")
save_map(x, "mean_microplastic", "Mean microplastic concentration by grid cell", "outputs/maps/mean_microplastic.png")
save_map(x, "species_richness", "Observed species richness by grid cell", "outputs/maps/species_richness.png")
save_flag_map(x, "pollution_hotspot", "Pollution hotspots", "outputs/maps/pollution_hotspots.png")
save_flag_map(x, "biodiversity_hotspot", "Biodiversity hotspots", "outputs/maps/biodiversity_hotspots.png")
save_flag_map(x, "effective_hotspot", "Effective hotspots", "outputs/maps/effective_hotspots.png")
save_map(x, "hotspot_score", "Pollution-biodiversity hotspot score", "outputs/maps/hotspot_score.png")
cluster <- readr::read_csv("outputs/tables/dbscan_results.csv", show_col_types = FALSE)
cluster_grid <- if ("cell_id" %in% names(cluster)) x |> dplyr::left_join(cluster, by = "cell_id") else x |> dplyr::mutate(dbscan_cluster = NA_integer_)
p <- ggplot2::ggplot(cluster_grid) + ggplot2::geom_sf(ggplot2::aes(fill = factor(dbscan_cluster)), colour = NA) + ggplot2::scale_fill_discrete(na.value = "grey90") + ggplot2::labs(title = "DBSCAN clusters of high-priority cells", fill = "Cluster", x = "Longitude", y = "Latitude") + ggplot2::coord_sf(expand = FALSE) + ggplot2::theme_minimal(base_size = 12)
ggplot2::ggsave("outputs/maps/dbscan_priority_clusters.png", p, width = 12, height = 7, dpi = 300)
fig <- ggplot2::ggplot(sf::st_drop_geometry(x), ggplot2::aes(hotspot_score)) + ggplot2::geom_histogram(bins = 30, fill = "#8856a7", colour = "white") + ggplot2::labs(title = "Hotspot score distribution", x = "P × B score", y = "Grid cells") + ggplot2::theme_minimal()
ggplot2::ggsave("outputs/figures/hotspot_score_distribution.png", fig, width = 8, height = 5, dpi = 300)
paired <- sf::st_drop_geometry(x) |> dplyr::filter(!is.na(hotspot_score))
if (nrow(paired) > 1) { p <- ggplot2::ggplot(paired, ggplot2::aes(biodiversity_occurrence_count, species_richness)) + ggplot2::geom_point(alpha = .7) + ggplot2::labs(title = "Species richness and sampling effort", x = "Biodiversity occurrence count", y = "Species richness") + ggplot2::theme_minimal(); ggplot2::ggsave("outputs/figures/richness_vs_sampling_effort.png", p, width = 7, height = 5, dpi = 300); p <- ggplot2::ggplot(paired, ggplot2::aes(microplastic_sample_count, mean_microplastic)) + ggplot2::geom_point(alpha = .7) + ggplot2::labs(title = "Microplastic concentration and sampling effort", x = "Microplastic sample count", y = "Mean microplastic concentration") + ggplot2::theme_minimal(); ggplot2::ggsave("outputs/figures/pollution_vs_sampling_effort.png", p, width = 7, height = 5, dpi = 300); p <- ggplot2::ggplot(paired, ggplot2::aes(microplastic_sample_count + biodiversity_occurrence_count, hotspot_score)) + ggplot2::geom_point(alpha = .7) + ggplot2::labs(title = "Hotspot score and combined sampling density", x = "Microplastic samples + biodiversity occurrences", y = "Hotspot score") + ggplot2::theme_minimal(); ggplot2::ggsave("outputs/figures/hotspot_score_vs_sampling_density.png", p, width = 7, height = 5, dpi = 300) }
summary <- sf::st_drop_geometry(x) |> dplyr::summarise(grid_cells = dplyr::n(), valid_paired_cells = sum(!is.na(hotspot_score)), pollution_hotspots = sum(pollution_hotspot, na.rm = TRUE), biodiversity_hotspots = sum(biodiversity_hotspot, na.rm = TRUE), effective_hotspots = sum(effective_hotspot, na.rm = TRUE))
readr::write_csv(summary, "outputs/tables/analysis_summary.csv")
report <- c("# Results report", "", "## Scope", "This report identifies observed overlap between reported microplastic concentration and observed species richness in a common Indian Ocean grid. It does not infer causality.", "", "## Dataset and grid summary", paste0("Grid cells: ", summary$grid_cells), paste0("Cells with both observation layers: ", summary$valid_paired_cells), "", "## Hotspot results", paste0("Pollution hotspots: ", summary$pollution_hotspots), paste0("Biodiversity hotspots: ", summary$biodiversity_hotspots), paste0("Effective hotspots: ", summary$effective_hotspots), "", "## Limitations", "Uneven sampling, temporal mismatch, heterogeneous microplastic methods, the chosen grid resolution, and occurrence-record bias can affect these observed patterns. Missing records remain missing; they are never treated as zero.")
writeLines(report, "outputs/results/results_report.md")
